  (* [comment removed for export] *)
  Definition in_data (x : word) : Prop :=
    (0x127000 <= bv_unsigned x < 0x138100)%Z \/ (0x158218 <= bv_unsigned x < 0x158438)%Z \/ (0x158890 <= bv_unsigned x < 0x159000)%Z.
