        pose proof (regs_ok_same (ENV vals1) sr Rc 12 (EVar 41) HR1 ltac:(intros H12; apply (f_equal bv_unsigned) in H12; discriminate H12)
                      ltac:(let e := eval vm_compute in (sr_get sr (12 : reg)) in
